// n8n Code node: "Normalize message" (mode: Run Once for All Items)
// Accepts items from Gmail Trigger (simple on/off), IMAP Email Trigger (simple or resolved format)
// and Microsoft Outlook Trigger (simplified or raw). Each trigger is followed by a "Tag mailbox" Set node
// that adds _mailbox (a label like "sales@gmail") and _provider (gmail | imap | outlook).
// Output: one flat item per message with the same field names, whatever mailbox it came from.

function parseAddress(v) {
  if (!v) return { email: '', name: '' };
  if (Array.isArray(v)) return parseAddress(v[0]);
  if (typeof v === 'object') {
    if (Array.isArray(v.value) && v.value.length) return { email: (v.value[0].address || '').toLowerCase(), name: v.value[0].name || '' };
    if (v.emailAddress) return { email: (v.emailAddress.address || '').toLowerCase(), name: v.emailAddress.name || '' };
    if (v.address) return { email: String(v.address).toLowerCase(), name: v.name || '' };
    if (v.text) return parseAddress(v.text);
    return { email: '', name: '' };
  }
  const s = String(v).trim();
  const m = s.match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>\s*$/);
  if (m) return { email: m[2].trim().toLowerCase(), name: m[1].trim() };
  const e = s.match(/[^\s<>"']+@[^\s<>"']+/);
  return { email: e ? e[0].toLowerCase() : '', name: '' };
}

function stripHtml(html) {
  return String(html || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|li|tr|h\d)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#39;|&apos;/g, "'").replace(/&quot;/g, '"');
}

// Drop quoted history so the classifier only sees what the sender actually wrote now.
function stripQuoted(text) {
  const out = [];
  for (const line of String(text).split(/\r?\n/)) {
    if (/^\s*>/.test(line)) continue;
    if (/^\s*On .{3,120} wrote:\s*$/i.test(line)) break;
    if (/^\s*-{2,}\s*Original Message\s*-{2,}/i.test(line)) break;
    if (/^\s*From: .+/i.test(line) && out.length > 2) break;
    out.push(line);
  }
  return out.join('\n').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
}

function hashKey(s) { // short stable id (FNV-1a) so the same message never gets two log rows
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(36);
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const provider = String(j._provider || '').toLowerCase() || (j.threadId ? 'gmail' : j.conversationId ? 'outlook' : 'imap');
  const mailbox = j._mailbox || provider;
  const from = parseAddress(j.from ?? j.From ?? j.sender);
  const subject = String(j.subject ?? j.Subject ?? '').trim();
  let body = j.text || j.textPlain || '';
  if (!body && (j.html || j.textHtml)) body = stripHtml(j.html || j.textHtml);
  if (!body && j.body && typeof j.body === 'object') body = j.body.contentType === 'html' ? stripHtml(j.body.content) : (j.body.content || '');
  if (!body) body = j.snippet || j.bodyPreview || '';
  body = stripQuoted(body).slice(0, 4000);
  const receivedRaw = j.date || j.Date || j.receivedDateTime || j.internalDate || '';
  let received = new Date(/^\d{12,}$/.test(String(receivedRaw)) ? Number(receivedRaw) : receivedRaw);
  if (isNaN(received)) received = new Date();
  const sourceId = String(j.id || j.messageId || (j.metadata && j.metadata['message-id']) || (j.attributes && j.attributes.uid) || '');
  const threadId = String(j.threadId || j.conversationId || (j.metadata && (j.metadata['in-reply-to'] || j.metadata['references'])) || '');
  const replyTo = parseAddress(j.replyTo || j['reply-to'] || (j.metadata && j.metadata['reply-to']));
  out.push({ json: {
    msg_key: provider + '-' + hashKey(mailbox + '|' + (sourceId || from.email + subject + received.toISOString())),
    received_at: received.toISOString(),
    mailbox, provider,
    source_id: sourceId,
    thread_id: threadId,
    from_email: from.email,
    from_name: from.name,
    reply_to: replyTo.email || from.email,
    subject: subject || '(no subject)',
    body,
    snippet: body.replace(/\s+/g, ' ').slice(0, 200),
  } });
}
return out;

// n8n Code node: "Classify & assign owner" (mode: Run Once for All Items)
// Keyword classifier: lead / support / billing / spam, plus "needs_triage" when nothing matches.
// It is deliberately simple and explainable: every decision lists the rules that fired (matched_rules).
// To use an LLM instead, put n8n's "Text Classifier" (AI) node here; keep the output field names.

// ===== EDIT ME: who owns what =====
const OWNERS = {
  lead:         [{ name: 'Sales (Ana)', email: 'ana@yourcompany.example' }],
  support:      [{ name: 'Support (Ben)', email: 'ben@yourcompany.example' }, { name: 'Support (Cy)', email: 'cy@yourcompany.example' }],
  billing:      [{ name: 'Billing (Di)', email: 'di@yourcompany.example' }],
  needs_triage: [{ name: 'Office manager', email: 'office@yourcompany.example' }],
  spam:         [{ name: '(nobody)', email: '' }],
};
// Sender domains that always go to a named owner (key accounts), whatever the category.
const DOMAIN_OWNERS = { 'bigclient.example': { name: 'Account manager (Eve)', email: 'eve@yourcompany.example' } };
// Senders that are never spam (your own domain, key suppliers).
const ALLOWLIST_DOMAINS = ['yourcompany.example'];
// ===================================

const RULES = {
  spam: [
    [/\b(guest post|backlinks?|seo (services|package|audit) for your|rank (you|your site) on (the )?first page)\b/i, 3],
    [/\b(crypto|bitcoin|forex|investment opportunity|lottery|you have won|inheritance)\b/i, 3],
    [/\b(web ?design|app development|lead generation) (services|agency) (for|to) (you|your)/i, 2],
    [/\bunsubscribe\b/i, 1], [/\b(limited time|act now|100% free|risk[- ]free)\b/i, 1],
  ],
  billing: [
    [/\b(invoice|receipt|billing|billed|charged?|charges|refund|chargeback|payment (failed|declined|issue)|credit card|subscription|renewal|vat|tax id)\b/i, 2],
    [/\b(cancel (my )?(plan|subscription|account)|double charged|overcharged|wrong amount)\b/i, 3],
  ],
  support: [
    [/\b(not working|doesn'?t work|broken|error|bug|crash(es|ed)?|can'?t (log ?in|login|access|find)|password reset|issue with|problem with|stopped working)\b/i, 2],
    [/\b(where is my order|tracking|delivery|shipped|return|exchange|damaged|missing item)\b/i, 2],
    [/\b(help|support|how do i|urgent)\b/i, 1],
  ],
  lead: [
    [/\b(quote|pricing|price list|how much|rates?|estimate|proposal|budget)\b/i, 2],
    [/\b(interested in|looking for (a|an|someone)|would like to (hire|book|order|work)|can you (build|help us|do)|book a (call|demo|meeting)|demo|consultation|partnership)\b/i, 2],
    [/\b(new project|our (company|team|business)|for (our|my) (store|clinic|agency|firm|restaurant))\b/i, 1],
  ],
};
const URGENT = /\b(urgent|asap|immediately|today|down|outage|chargeback|legal|lawyer)\b/i;

function pick(list, key) { // stable round-robin by message key: same message -> same owner, no state needed
  let h = 0; for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) >>> 0;
  return list[h % list.length];
}

return $input.all().map(({ json: m }) => {
  const domain = (m.from_email.split('@')[1] || '').toLowerCase();
  const subj = m.subject || ''; const body = m.body || '';
  const scores = {}; const fired = [];
  for (const [cat, rules] of Object.entries(RULES)) {
    scores[cat] = 0;
    for (const [re, w] of rules) {
      const inSubj = re.test(subj), inBody = re.test(body);
      if (inSubj || inBody) { scores[cat] += w * (inSubj ? 2 : 1); fired.push(cat + ':' + (re.source.match(/\(([^)|]{3,30})/) || [, re.source.slice(0, 20)])[1]); }
    }
  }
  if (ALLOWLIST_DOMAINS.includes(domain)) scores.spam = 0;
  // spam only wins when it clearly outscores real intent
  let category = 'needs_triage'; let best = 0;
  for (const cat of ['billing', 'support', 'lead']) if (scores[cat] > best) { best = scores[cat]; category = cat; }
  if (scores.spam >= 3 && scores.spam > best) { category = 'spam'; best = scores.spam; }
  const total = Object.values(scores).reduce((a, b) => a + b, 0) || 1;
  const confidence = category === 'needs_triage' ? 0 : Math.round((best / total) * 100) / 100;
  const owner = DOMAIN_OWNERS[domain] && category !== 'spam' ? DOMAIN_OWNERS[domain] : pick(OWNERS[category], m.msg_key);
  const priority = category === 'spam' ? 'none' : (URGENT.test(subj + ' ' + body) || (category === 'lead' && /\bbudget\b/i.test(body))) ? 'high' : 'normal';
  return { json: { ...m, category, confidence, matched_rules: fired.join(', '), owner: owner.name, owner_email: owner.email, priority } };
});

// n8n Code node: "Draft reply (needs approval)" (mode: Run Once for All Items)
// Writes a short template reply per category. NOTHING IS SENT HERE.
// status = pending_approval: a human must change it to "approved" in the log sheet (optionally editing
// final_reply first). Only then does the "Send approved replies" branch send it.
// Spam gets no draft and status = ignored_spam. Swap this node for an AI Agent / OpenAI node if you
// prefer AI drafts; keep the same output fields so the approval step still applies.

// ===== EDIT ME =====
const SIGNATURE = '\n\nBest,\nThe YourCompany team';
const LINKS = { booking: 'https://cal.com/yourcompany/intro', status: 'https://status.yourcompany.example' };
// ===================

function firstName(m) {
  const n = (m.from_name || '').trim().split(/\s+/)[0];
  return n && /^[\p{L}'-]{2,}$/u.test(n) ? n : 'there';
}
const T = {
  lead: m => `Hi ${firstName(m)},\n\nThanks for reaching out about "${m.subject}". ${m.owner.replace(/^.*\((.*)\)$/, '$1')} will look after you personally.\n\nTo give you an accurate answer, could you share (1) what you want to achieve, (2) your timeline and (3) a rough budget range? If it is easier to talk, pick a 15-minute slot here: ${LINKS.booking}`,
  support: m => `Hi ${firstName(m)},\n\nThanks for letting us know. We have logged your message ("${m.subject}") and ${m.owner.replace(/^.*\((.*)\)$/, '$1')} is looking into it.\n\nIf you can, reply with a screenshot, the time it happened and any error text, so we can reproduce it faster. Live status: ${LINKS.status}`,
  billing: m => `Hi ${firstName(m)},\n\nThanks for your message about "${m.subject}". Our billing team has it and will check your account.\n\nPlease reply with the invoice number or the last 4 digits of the card used, never the full card number.`,
  needs_triage: m => `Hi ${firstName(m)},\n\nThanks for your email ("${m.subject}"). We have received it and the right person will get back to you shortly.`,
};

const nowIso = new Date().toISOString();
return $input.all().map(({ json: m }) => {
  const isSpam = m.category === 'spam';
  const draft = isSpam ? '' : T[m.category](m) + SIGNATURE;
  return { json: {
    msg_key: m.msg_key, received_at: m.received_at, mailbox: m.mailbox, provider: m.provider,
    source_id: m.source_id, thread_id: m.thread_id, from_email: m.from_email, from_name: m.from_name, reply_to: m.reply_to,
    subject: m.subject, snippet: m.snippet, category: m.category, confidence: m.confidence, matched_rules: m.matched_rules,
    owner: m.owner, owner_email: m.owner_email, priority: m.priority,
    draft_reply: draft, final_reply: '',
    status: isSpam ? 'ignored_spam' : 'pending_approval',
    approved_by: '', sent_at: '', logged_at: nowIso,
  } };
});

